#!/bin/bash
#
# Copyright (C) 2026 Intel Corporation
#
# SPDX-License-Identifier: MIT
#
# Splits a Go coverage profile into two:
# a) hand-written code
# b) auto-generated code
#
# Usage: coverage-report.sh <module-dir> <profile>

set -e -u -o pipefail

GENERATED_MARKER='^// *Code generated by'

if [ $# -ne 2 ]; then
    echo "Usage: ${0##*/} <module-dir> <profile>"
    exit 1
fi

PROFILE=$(realpath "$2")
# Base name of the reports, 'coverage/go-module'
PREFIX="${PROFILE%.*}"

cd "$1"

# The file names of a profile are import paths, i.e. the module path followed by
# the path of the file within the module.
MODULE=$(go list -m)

generated=$(mktemp)
# shellcheck disable=SC2064  # expand the file name now, not on exit
trap "rm -f '${generated}'" EXIT

# A module without any generated code makes git-grep fail, any other failure is an error.
git grep --no-full-name -l -E "${GENERATED_MARKER}" -- '*.go' |
    sed -e "s|^|${MODULE}/|" > "${generated}" || [ $? -eq 1 ]

# Use ':' as the field separator (no colon in our file names so the first field is the name of the file)
awk -F: \
    -v generated_list="${generated}" \
    -v hand_written_profile="${PREFIX}-hand-written.out" \
    -v generated_profile="${PREFIX}-generated.out" '
# Read the file that contains the list of generated files, convert to a set, keyed by file name.
BEGIN {
    while ((getline file < generated_list) > 0)
        generated[file] = 1
}

# Both buckets need the mode header of the original profile.
/^mode:/ {
    print > hand_written_profile
    print > generated_profile
    next
}

# Finally, read/split the profile. Write each line of the profile into the corresponding bucket (generated vs. hand-written),
# depending whether the file name is in the set of generated files.
{
    profile = ($1 in generated) ? generated_profile : hand_written_profile
    print > profile
}' "${PROFILE}"

# Writes the reports of one half and prints its total coverage.
report() {
    local profile="${PREFIX}-$1.out"
    local txt_report="${PREFIX}-$1.txt"
    local html_report="${PREFIX}-$1.html"

    # Nothing but the mode header: the module has no code of this kind. Drop all
    # artifacts of the bucket so that no stale report of a previous run is left
    # behind.
    if [ ! -s "${profile}" ] || [ "$(wc -l < "${profile}")" -le 1 ]; then
        rm -f "${profile}" "${txt_report}" "${html_report}"
        echo "n/a"
        return
    fi

    go tool cover -func="${profile}" > "${txt_report}" || return 1
    go tool cover -html="${profile}" -o "${html_report}" || return 1
    # The last value on the last line of the txt report is the total
    tail -1 "${txt_report}" | awk '{print $NF}'
}

hand_written_total=$(report hand-written)
generated_total=$(report generated)

echo "${MODULE}: hand-written ${hand_written_total}, generated ${generated_total}"
